Object.assign(PROPS2, {
  /* la règle de bâtisseur de Chammaï (amat habinyan), graduée */
  tmCubit(P, A, J, M, h, t, lw, F, u, n, add) {
    const a = add(A.w, u, -0.14), b = add(A.w, u, 0.44), Ms = q => q.map(M), L = 0.58;
    P.shape(Ms([add(a, n, 0.009), add(b, n, 0.009), add(b, n, -0.009), add(a, n, -0.009)]), 'r4y6k2', lw * 0.7);
    for (let k = 1; k < 9; k++) { const c = add(a, u, L * k / 9); P.line(Ms([add(c, n, 0.009), add(c, n, k % 3 ? 0.002 : -0.006)]), lw * 0.45); }
  },
  /* deux bouquets de myrte, un par main */
  tmMyrtle(P, A, J, M, h, t, lw, F, u, n, add) {
    const q = M(A.t), s = h / 140, sw = Math.sin(t * 5 + (F.x || 0)) * 1.5 * s;
    P.line([[q[0], q[1] + 3 * s], [q[0] + sw, q[1] - 26 * s]], lw * 0.9);
    for (let i = 0; i < 7; i++) { const y = q[1] - 4 * s - i * 3.4 * s, x = q[0] + sw * i / 7; for (const d of [-1, 1]) P.shape([[x, y], [x + d * 5 * s, y - 2.5 * s], [x + d * 6 * s, y - 4.5 * s], [x + d * 1.5 * s, y - 2.8 * s]], i % 2 ? 'y4b6k1' : 'y5b6k2', lw * 0.35); }
    P.fill(P.disc(q[0] + sw, q[1] - 27 * s, 2.4 * s, 6), 'y4b6k1', {});
  },
  /* lyre des Lévites, cordes qui vibrent */
  tmLyre(P, A, J, M, h, t, lw, F) {
    const q = M(A.w), s = h / 140, fc = F.face || 1, X = (a, b) => [q[0] + fc * a * s, q[1] + b * s];
    P.shape([X(-10, 8), X(12, 8), X(12, 18), X(-10, 18)], 'r5y5k2', lw * 0.8);
    P.shape([X(-10, 9), X(-15, -8), X(-12, -26), X(-7, -27), X(-9, -8), X(-5, 9)], 'r4y6k2', lw * 0.7);
    P.shape([X(12, 9), X(17, -8), X(15, -28), X(10, -29), X(12, -8), X(7, 9)], 'r4y6k2', lw * 0.7);
    P.line([X(-13, -24), X(16, -26)], lw * 1.6, { ink: 3, taper: 0 });
    for (let i = 0; i < 5; i++) { const x = -5 + i * 4, v = Math.sin(t * 40 + i) * 0.6; P.line([X(x, 9), X(x + v, -8), X(x, -24.5 + i * -0.3)], lw * 0.4, { ink: 3, lvl: 7 }); }
  },
  /* trompette d'argent, pavillon levé */
  tmTrumpet(P, A, J, M, h, t, lw, F) {
    const m = [J.head[0] + J.hf[0] * 0.075 - J.hu[0] * 0.03, J.head[1] + J.hf[1] * 0.075 - J.hu[1] * 0.03], e = [m[0] + 0.34, m[1] - 0.1];
    P.shape([M([m[0], m[1] - 0.007]), M([e[0], e[1] - 0.009]), M([e[0], e[1] + 0.009]), M([m[0], m[1] + 0.007])], 'b1k3', lw * 0.6);
    P.shape([M([e[0] - 0.02, e[1] - 0.012]), M([e[0] + 0.03, e[1] - 0.05]), M([e[0] + 0.045, e[1] + 0.03]), M([e[0] - 0.02, e[1] + 0.012])], 'b1y2k2', lw * 0.7);
    F.out.horn = M([e[0] + 0.05, e[1] - 0.01]);
  },
  tmCymbals(P, A, J, M, h, t, lw) { const q = M(A.t), s = h / 140; P.shape(P.disc(q[0], q[1], 7 * s, 14).map(p => [p[0], q[1] + (p[1] - q[1]) * 0.45]), 'y7r3', lw * 0.6); P.fill(P.disc(q[0], q[1], 2 * s, 8), 'y8r4k1', {}); },
  /* cruche d'huile tenue à bout de bras, pour remplir les coupes */
  tmOilJar(P, A, J, M, h, t, lw, F) {
    const q = M(A.t), s = h / 140, fc = F.face || 1, X = (a, b) => [q[0] + fc * a * s, q[1] + b * s];
    P.shape([X(-6, 4), X(6, 2), X(10, -8), X(8, -18), X(3, -22), X(-3, -21), X(-7, -14), X(-9, -4)], 'r5y6k1', lw * 0.8);
    P.line([X(3, -22), X(8, -27), X(14, -26)], lw * 1.4);
    const k = (t * 0.8) % 1; P.fill(P.disc(X(14, -24 + k * 16)[0], X(14, -24 + k * 16)[1], 1.6 * s, 6), 'y7r2', { noKnock: true });
  },
  /* le coffret de pierres précieuses, tenu sur les genoux */
  tmChest(P, A, J, M, h, t, lw) {
    const c = [(J.aN.t[0] + J.aF.t[0]) / 2, (J.aN.t[1] + J.aF.t[1]) / 2 + 0.01], q = M(c), s = h / 140;
    P.shape([[q[0] - 13 * s, q[1] - 7 * s], [q[0] + 13 * s, q[1] - 7 * s], [q[0] + 13 * s, q[1] + 8 * s], [q[0] - 13 * s, q[1] + 8 * s]], 'r5y5k3', lw * 0.8);
    P.shape([[q[0] - 14 * s, q[1] - 7 * s], [q[0] - 11 * s, q[1] - 13 * s], [q[0] + 11 * s, q[1] - 13 * s], [q[0] + 14 * s, q[1] - 7 * s]], 'r5y5k2', lw * 0.7);
    for (const x of [-8, 8]) P.fill([[q[0] + (x - 1.5) * s, q[1] - 12 * s], [q[0] + (x + 1.5) * s, q[1] - 12 * s], [q[0] + (x + 1.5) * s, q[1] + 8 * s], [q[0] + (x - 1.5) * s, q[1] + 8 * s]], 'y7r2', {});
    P.fill(P.disc(q[0], q[1] - 3 * s, 2 * s, 6), 'y8r3', {});
  },
  /* le choffar, embouchure aux lèvres */
  tmShofar(P, A, J, M, h, t, lw, F) {
    const m = [J.head[0] + J.hf[0] * 0.075 - J.hu[0] * 0.03, J.head[1] + J.hf[1] * 0.075 - J.hu[1] * 0.03], pts = [];
    for (let i = 0; i <= 10; i++) { const s = i / 10; pts.push([m[0] + s * 0.34, m[1] - Math.sin(s * 2.2) * 0.07 - s * s * 0.18]); }
    const w0 = 0.008, w1 = 0.046, top = pts.map((p, i) => [p[0], p[1] - lerp(w0, w1, i / 10)]), bot = pts.map((p, i) => [p[0], p[1] + lerp(w0, w1, i / 10)]);
    P.shape(top.concat(bot.reverse()).map(M), 'y5r3k1', lw * 0.8);
    for (let i = 2; i < 10; i += 2) P.line([M([pts[i][0], pts[i][1] - lerp(w0, w1, i / 10)]), M([pts[i][0] + 0.004, pts[i][1] + lerp(w0, w1, i / 10)])], lw * 0.4);
    F.out.horn = M([pts[10][0] + 0.02, pts[10][1]]);
  },
  /* livre de prières ouvert */
  tmBook(P, A, J, M, h, t, lw) {
    const c = [(J.aN.t[0] + J.aF.t[0]) / 2, (J.aN.t[1] + J.aF.t[1]) / 2 - 0.02], q = M(c), w = h * 0.06, e = h * 0.045;
    for (const s of [-1, 1]) { P.shape([[q[0], q[1] - e * 0.3], [q[0] + s * w, q[1] - e * 0.6], [q[0] + s * w, q[1] + e * 0.6], [q[0], q[1] + e * 0.85]], 'y1', lw * 0.6); for (let i = 0; i < 3; i++) P.line([[q[0] + s * w * 0.2, q[1] - e * 0.2 + i * e * 0.28], [q[0] + s * w * 0.8, q[1] - e * 0.4 + i * e * 0.28]], lw * 0.3); }
  },
  /* jeune caroubier tenu à deux mains avant d'être planté */
  tmSapling(P, A, J, M, h, t, lw) {
    const c = [(J.aN.t[0] + J.aF.t[0]) / 2, (J.aN.t[1] + J.aF.t[1]) / 2], q = M(c), s = h / 140;
    P.shape([[q[0] - 6 * s, q[1]], [q[0] + 6 * s, q[1]], [q[0] + 4 * s, q[1] + 8 * s], [q[0] - 4 * s, q[1] + 8 * s]], 'r5y4k3', lw * 0.6);
    P.line([[q[0], q[1]], [q[0] + 1, q[1] - 22 * s]], lw * 1.1);
    P.shape(Lib.bumpy(P, q[0] + 1, q[1] - 26 * s, 10 * s, 7 * s, 6), 'y4b6k2', lw * 0.6);
  }
});
