/* maison de pierre à toit plat : porte en arc sur la face avant gauche (dx) ou droite (dy), fenêtres */
const tmHouse = (P, x, y, w, d, h, tn, o = {}) => {
  P.box(x, y, 0, w, d, h, tn);
  for (let z = 15; z < h - 4; z += 15) { P.line([P.I(x, y + d, z), P.I(x + w, y + d, z)], 0.35); P.line([P.I(x + w, y, z), P.I(x + w, y + d, z)], 0.35); }
  P.box(x - 2, y - 2, h, w + 4, 5, 7, tadd(tn, 'k1'), 0.6); P.box(x - 2, y - 2, h, 5, d + 4, 7, tadd(tn, 'k1'), 0.6);
  P.box(x - 2, y + d - 3, h, w + 4, 5, 7, tadd(tn, 'y1'), 0.6); P.box(x + w - 3, y - 2, h, 5, d + 4, 7, tadd(tn, 'y1'), 0.6);
  const arch = (F, a0, dw, dh, tone) => { const pts = [F(a0, 0), F(a0 + dw, 0), F(a0 + dw, dh - dw / 2)]; for (let i = 0; i <= 8; i++) { const a = Math.PI * i / 8; pts.push(F(a0 + dw / 2 + Math.cos(a) * dw / 2, dh - dw / 2 + Math.sin(a) * dw / 2)); } pts.push(F(a0, dh - dw / 2)); P.shape(pts, tone, 0.9); };
  const FL = (a, z) => P.I(x + a, y + d + 0.5, z), FR = (a, z) => P.I(x + w + 0.5, y + a, z);
  if (o.dx !== undefined) { arch((a, z) => FL(a - 4, z), o.dx, 32, 58, tadd(tn, 'k2')); arch(FL, o.dx, 24, 50, o.door || 'k6r2'); }
  if (o.dy !== undefined) { arch((a, z) => FR(a - 4, z), o.dy, 32, 58, tadd(tn, 'k2')); arch(FR, o.dy, 24, 50, o.door || 'k6r2'); }
  for (const [side, a, z] of o.win || []) { const F = side ? FR : FL; P.shape([F(a, z), F(a + 12, z), F(a + 12, z + 16), F(a, z + 16)], o.winTn || 'k6b2', 0.7); P.line([F(a + 6, z), F(a + 6, z + 16)], 0.5); }
};
