    for (let v = (k % 2) * 22 + r() * 10; v < L; v += 44 + r() * 8) { P.line([P.I(0.5, v, z - 18), P.I(0.5, v, z)], 0.3); P.line([P.I(v, 0.5, z - 18), P.I(v, 0.5, z)], 0.3); }
