const tmPave = (P, step, lw = 0.35) => { for (let v = step; v < P.L; v += step) { P.line([P.I(v, 0, 0), P.I(v, P.L, 0)], lw); P.line([P.I(0, v, 0), P.I(P.L, v, 0)], lw); } };
