/* un cyprès */
const tmCypress = (P, x, y, h = 150) => { const b = P.I(x, y, 0); P.line([b, [b[0], b[1] - 16]], 3); const w = u => 15 * Math.pow(Math.sin(Math.PI * Math.min(1, 0.22 + u * 0.78)), 0.75) * (1 + 0.06 * Math.sin(u * 23)), R = [], Lf = []; for (let i = 0; i <= 16; i++) { const u = i / 16, yy = b[1] - 12 - u * h; R.push([b[0] + w(u), yy]); Lf.push([b[0] - w(u) * 0.9, yy]); } P.shape(R.concat(Lf.reverse()), 'y4b7k2', 1); P.fill(R.map((p, i) => [b[0] + (p[0] - b[0]) * 0.35, p[1]]).concat(R.slice().reverse()), 'y4b7k3', { noKnock: true }); for (let i = 2; i < 15; i += 2) { const yy = b[1] - 12 - i / 16 * h; P.line([[b[0] - 6, yy + 4], [b[0] + 2, yy], [b[0] + 8, yy + 5]], 0.5); } };
/* silhouette lumineuse d'ange, sans visage */
const tmAngel = (P, b, h, t, o = {}) => {
  const bob = Math.sin(t * 1.5 + (o.ph || 0)) * 3, x = b[0], y = b[1] - bob - (o.lift || 6), s = h, good = !o.bad;
  const tn = good ? 'y1' : 'b2k2', edge = good ? { ink: 0, lvl: 7 } : { ink: 2, lvl: 7 };
  if (good) P.halo(x, y - s * 0.5, s * 0.62, ['y1', 'y1', 'y2', 'y2r1'], { sq: 1.25 }); else P.halo(x, y - s * 0.5, s * 0.5, ['b1', 'b1k1', 'b2k1'], { sq: 1.25 });
  const fl = Math.sin(t * 2 + (o.ph || 0)) * 3;
  for (const sg of [-1, 1]) {
    P.shape([[x + sg * s * 0.05, y - s * 0.72], [x + sg * s * 0.2, y - s * 0.94 - fl], [x + sg * s * 0.34, y - s * 1.02 - fl], [x + sg * s * 0.31, y - s * 0.8], [x + sg * s * 0.24, y - s * 0.58], [x + sg * s * 0.1, y - s * 0.46]], good ? 'y2' : 'b3k2', 0.7, edge);
    for (let i = 1; i < 4; i++) P.line([[x + sg * s * 0.08, y - s * 0.62], [x + sg * s * (0.12 + i * 0.06), y - s * (0.8 + i * 0.05) - fl * i / 3]], 0.45, edge);
  }
  const hem = []; for (let i = 0; i <= 8; i++) { const u = i / 8; hem.push([x + s * (0.19 - 0.38 * u), y - s * 0.02 + Math.sin(u * TAU * 2 + t * 2) * 1.5]); }
  P.shape([[x - s * 0.09, y - s * 0.76], [x + s * 0.09, y - s * 0.76], [x + s * 0.13, y - s * 0.5], [x + s * 0.19, y - s * 0.02]].concat(hem.slice(1, -1), [[x - s * 0.19, y - s * 0.02], [x - s * 0.13, y - s * 0.5]]), tn, 0.8, edge);
  for (let i = -1; i <= 1; i++) P.line([[x + i * s * 0.04, y - s * 0.62], [x + i * s * 0.1, y - s * 0.06]], 0.4, edge);
  if (good) { P.shape([[x + s * 0.08, y - s * 0.7], [x + s * 0.26, y - s * 0.86], [x + s * 0.29, y - s * 0.82], [x + s * 0.12, y - s * 0.62]], tn, 0.6, edge); }
  else { P.shape([[x - s * 0.08, y - s * 0.7], [x - s * 0.14, y - s * 0.46], [x - s * 0.1, y - s * 0.44], [x - s * 0.04, y - s * 0.66]], tn, 0.6, edge); }
  const hy = good ? y - s * 0.86 : y - s * 0.83;
  P.shape(P.disc(good ? x : x - s * 0.02, hy, s * 0.075, 16), tn, 0.8, edge);
};
/* objets de table (P, t, z) */
