/* menorah d'or de la cour des femmes : quatre coupes, quatre échelles ; renvoie les coupes */
const tmMenorahPts = (x, y, H) => [[x - 26, y], [x + 26, y], [x, y - 26], [x, y + 26]].map(([a, b]) => [a, b, H + 10]);
const tmMenorah = (P, x, y, H) => {
  const g = 'y7r2', gd = 'y7r3k1';
  P.box(x - 22, y - 22, 0, 44, 44, 12, 'y3r2k2', 0.9); P.box(x - 15, y - 15, 12, 30, 30, 8, gd, 0.8);
  P.cyl(x, y, 20, 8, H - 20, g, 0.9, 16);
  for (let z = 60; z < H - 20; z += 70) P.cyl(x, y, z, 11, 7, gd, 0.6, 16);
  for (const [dx, dy] of [[-26, 0], [26, 0], [0, -26], [0, 26]]) { P.line([P.I(x, y, H - 16), P.I(x + dx, y + dy, H + 2)], 3.2, { ink: 0, lvl: 8, taper: 0 }); P.line([P.I(x, y, H - 16), P.I(x + dx, y + dy, H + 2)], 0.7); }
  for (const [bx, by, bz] of tmMenorahPts(x, y, H).sort((a, b) => a[0] + a[1] - b[0] - b[1])) { P.cyl(bx, by, bz - 10, 11, 8, g, 0.8, 16); P.shape(P.ell(bx, by, bz - 1.6, 8, 8, 14), 'y8r4', 0.5); }
};
const tmLadder = (P, x0, y0, x1, y1, z1, w = 12) => {
  const n = [(y1 - y0), -(x1 - x0)], l = Math.hypot(n[0], n[1]) || 1, nx = n[0] / l * w / 2, ny = n[1] / l * w / 2;
  for (const s of [-1, 1]) P.line([P.I(x0 + s * nx, y0 + s * ny, 0), P.I(x1 + s * nx, y1 + s * ny, z1)], 2.2, { ink: 3, lvl: 7, taper: 0 });
  for (let i = 1; i < 12; i++) { const k = i / 12; P.line([P.I(lerp(x0, x1, k) - nx, lerp(y0, y1, k) - ny, z1 * k), P.I(lerp(x0, x1, k) + nx, lerp(y0, y1, k) + ny, z1 * k)], 1.1, { ink: 3, lvl: 7, taper: 0 }); }
};
