    for (const [a, b] of [[120, 250], [440, 330], [300, 300]]) { const q = P.I(a, b, 0); P.fill(P.disc(q[0], q[1], 170, 40).map(p => [p[0], q[1] + (p[1] - q[1]) * 0.55]), 'y4r3k1', {}); P.fill(P.disc(q[0], q[1], 100, 40).map(p => [p[0], q[1] + (p[1] - q[1]) * 0.55]), 'y3r2', {}); }
    tmPave(P, 45, 0.4);
    tmStoneWalls(P, 'y3r2b1k2', 220, { seed: 71 });
    for (const [x, y] of [[120, 250], [440, 330]]) { const q = P.I(x, y, 290); P.halo(q[0], q[1] - 16, 96, ['y1', 'y2', 'y3r1', 'y4r2'], { knock: true, sq: 0.8 }); }
    /* la galerie des femmes le long du mur gauche */
    P.box(0, 40, 118, 40, 470, 6, 'r4y5k2', 0.8);
    for (let y = 60; y < 510; y += 64) P.box(34, y, 0, 6, 6, 118, 'r4y5k3', 0.6);
